<template><div class="system-page"><div class="page-head"><div><h1>角色权限管理</h1><p>配置不同岗位能看到哪些模块、能执行哪些操作，以及默认数据范围。</p></div><el-button type="primary" @click="openCreate">新增角色</el-button></div><div class="layout2"><div class="card"><div class="toolbar"><el-input v-model="keyword" placeholder="搜索角色" clearable @keyup.enter="loadRoles"/><el-switch v-model="showLegacy" active-text="显示历史角色" @change="loadRoles"/></div><el-table :data="roles" highlight-current-row @row-click="selectRole" style="margin-top:12px"><el-table-column label="角色"><template #default="{row}"><b>{{row.name}}</b><div class="muted">{{row.code}}</div><el-tag v-if="row.is_builtin" size="small">内置</el-tag><el-tag v-if="row.is_legacy" size="small" type="info">历史</el-tag></template></el-table-column><el-table-column prop="data_scope_name" label="数据范围" width="100"/><el-table-column prop="permission_count" label="权限" width="70"/></el-table></div><div class="card" v-if="current"><el-tabs v-model="tab"><el-tab-pane label="基础信息" name="base"><el-form label-width="90px"><el-form-item label="角色名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="角色编码"><el-input v-model="form.code" :disabled="!!current.id"/></el-form-item><el-form-item label="描述"><el-input v-model="form.description"/></el-form-item><el-form-item label="数据范围"><el-select v-model="form.data_scope"><el-option v-for="d in scopes" :key="d.value" :label="d.label" :value="d.value"/></el-select></el-form-item><el-form-item label="状态"><el-switch v-model="form.status" :active-value="1" :inactive-value="0"/></el-form-item><el-button type="primary" @click="saveRole">保存基础信息</el-button><el-button type="danger" @click="disableRole" v-if="current.id">停用角色</el-button></el-form></el-tab-pane><el-tab-pane label="模块权限" name="perm"><el-scrollbar height="560px"><div v-for="g in permissionGroups" :key="g.module" class="card"><h3>{{g.module_name}}</h3><el-checkbox-group v-model="checked"><el-checkbox v-for="p in g.permissions" :key="p.id" :label="p.id">{{p.name}} <span class="muted">{{p.code}}</span></el-checkbox></el-checkbox-group></div></el-scrollbar><el-button type="primary" @click="savePerm">保存权限</el-button></el-tab-pane><el-tab-pane label="数据范围" name="scope"><el-radio-group v-model="form.data_scope"><el-radio-button v-for="d in scopes" :key="d.value" :label="d.value">{{d.label}}</el-radio-button></el-radio-group><div style="margin-top:16px"><el-button type="primary" @click="saveScope">保存数据范围</el-button></div></el-tab-pane></el-tabs></div><el-empty v-else class="card" description="请选择一个角色"/></div><el-dialog v-model="createVisible" title="新增角色"><el-form label-width="90px"><el-form-item label="角色名称"><el-input v-model="createForm.name"/></el-form-item><el-form-item label="角色编码"><el-input v-model="createForm.code"/></el-form-item><el-form-item label="数据范围"><el-select v-model="createForm.data_scope"><el-option v-for="d in scopes" :key="d.value" :label="d.label" :value="d.value"/></el-select></el-form-item></el-form><template #footer><el-button @click="createVisible=false">取消</el-button><el-button type="primary" @click="createRole">创建</el-button></template></el-dialog></div></template><script setup lang="ts">import{onMounted,ref,reactive}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import{systemApi}from'@/api/system';const roles=ref<any[]>([]),current=ref<any>(),permissionGroups=ref<any[]>([]),checked=ref<number[]>([]),keyword=ref(''),showLegacy=ref(false),tab=ref('base'),createVisible=ref(false);const scopes=[{label:'全部数据',value:'all'},{label:'公司数据',value:'company'},{label:'部门数据',value:'dept'},{label:'门店数据',value:'store'},{label:'个人数据',value:'self'}];const form=reactive<any>({});const createForm=reactive({name:'',code:'',data_scope:'self',status:1});async function loadRoles(){const r=await systemApi.getRoles({keyword:keyword.value,show_legacy:showLegacy.value});roles.value=r.data.data||[]}async function selectRole(r:any){current.value=r;Object.assign(form,r);const p=await systemApi.getRolePermissions(r.id);permissionGroups.value=p.data.data.groups;checked.value=p.data.data.checked_permission_ids}function openCreate(){Object.assign(createForm,{name:'',code:'',data_scope:'self',status:1});createVisible.value=true}async function createRole(){await systemApi.createRole(createForm);ElMessage.success('角色已创建');createVisible.value=false;loadRoles()}async function saveRole(){await systemApi.updateRole(current.value.id,form);ElMessage.success('角色已保存');loadRoles()}async function savePerm(){await systemApi.updateRolePermissions(current.value.id,{permission_ids:checked.value});ElMessage.success('权限已保存');selectRole(current.value)}async function saveScope(){await systemApi.updateRoleDataScope(current.value.id,{data_scope:form.data_scope});ElMessage.success('数据范围已保存');loadRoles()}async function disableRole(){await ElMessageBox.confirm('确认停用并隐藏该角色？','提示');await systemApi.deleteRole(current.value.id);ElMessage.success('角色已停用');current.value=null;loadRoles()}onMounted(loadRoles)</script>
<style scoped>.system-page{padding:24px;background:#f6f8fb;min-height:100%}.page-head{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:18px}.page-head h1{margin:0;color:#0f172a;font-size:26px}.page-head p{margin:8px 0 0;color:#64748b}.card{background:#fff;border:1px solid #e5eaf2;border-radius:8px;padding:18px;margin-bottom:16px;box-shadow:0 1px 2px rgba(15,23,42,.035)}.toolbar{display:flex;gap:10px;flex-wrap:wrap;align-items:center}.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}.stat{background:#fff;border:1px solid #e5eaf2;border-radius:8px;padding:18px}.stat b{font-size:28px;color:#0f172a}.stat span{display:block;color:#64748b;margin-top:6px}.layout2{display:grid;grid-template-columns:360px 1fr;gap:16px}.muted{color:#94a3b8;font-size:12px}.jsonbox{max-height:280px;overflow:auto;background:#f8fafc;color:#334155;border:1px solid #e5eaf2;padding:12px;border-radius:8px;font-size:12px;white-space:pre-wrap}@media(max-width:1100px){.layout2{grid-template-columns:1fr}.stats{grid-template-columns:repeat(2,1fr)}}
</style>
